import { useEffect, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { updateActivity, forceLogout } from '../store/slices/authSlice';

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes in milliseconds

export const useSessionTimeout = () => {
  const dispatch = useDispatch();
  const { isAuthenticated, lastActivity } = useSelector((state) => state.auth);
  const timeoutRef = useRef(null);

  useEffect(() => {
    if (!isAuthenticated) return;

    // Update activity on user interaction
    const updateActivityOnInteraction = () => {
      dispatch(updateActivity());
    };

    // Add event listeners for user activity
    const events = ['mousedown', 'mousemove', 'keypress', 'scroll', 'touchstart', 'click'];
    
    events.forEach(event => {
      document.addEventListener(event, updateActivityOnInteraction, true);
    });

    // Check for session timeout
    const checkSessionTimeout = () => {
      if (!lastActivity) return;

      const now = Date.now();
      const timeSinceLastActivity = now - lastActivity;

      if (timeSinceLastActivity > SESSION_TIMEOUT) {
        console.log('🕒 Session timeout - forcing logout');
        dispatch(forceLogout());
      }
    };

    // Check timeout every minute
    timeoutRef.current = setInterval(checkSessionTimeout, 60 * 1000);

    // Cleanup
    return () => {
      events.forEach(event => {
        document.removeEventListener(event, updateActivityOnInteraction, true);
      });
      
      if (timeoutRef.current) {
        clearInterval(timeoutRef.current);
      }
    };
  }, [dispatch, isAuthenticated, lastActivity]);

  // Set initial activity timestamp when user logs in
  useEffect(() => {
    if (isAuthenticated && !lastActivity) {
      dispatch(updateActivity());
    }
  }, [dispatch, isAuthenticated, lastActivity]);
};

export default useSessionTimeout;
